import sailpoint.object.ResourceObject;

// ---------------------------------------------------------------------------
// TODO 1: Disable suspended accounts.
//   If the "status" attribute equals "SUSPENDED", set the reserved attribute
//   "IIQDisabled" to Boolean true. (Check status for null first.)
//   Verify: bwilliams and rbrown show as disabled after aggregation.
//
// TODO 2: Lowercase the login.
//   "JTaylor" comes back mixed-case. Lowercase the "login" attribute.
//   Hint: login is your Display Attribute, so also call
//   object.setDisplayName(...) with the lowercased value.
//
// TODO 3: Build a full name.
//   Combine firstName + " " + lastName into a new attribute "fullName"
//   (add fullName to the account schema first, or it won't be stored).
//   Handle either part being null.
//
// TODO 4: Log what you did.
//   log.debug("AcmeHR customization: " + object.getIdentity() + " ...");
//   Turn on rule logging at debug to see it.
//
// STRETCH: if "roles" contains "R400" (System Admin), set a new
//   attribute "privilegedAccount" = true. roles is multi-valued, so it
//   comes back as a List.
// ---------------------------------------------------------------------------

return object;
